// WRONG: same group in two different services
@KafkaListener(topics = "orders", groupId = "orders-consumer")   // in email-service
@KafkaListener(topics = "orders", groupId = "orders-consumer")   // in invoice-service

// RIGHT: one group per service
@KafkaListener(topics = "orders", groupId = "email-service")
@KafkaListener(topics = "orders", groupId = "invoice-service")

# application.yml
spring:
  kafka:
    bootstrap-servers: kafka:9092
    producer:
      value-serializer: org.springframework.kafka.support.serializer.JsonSerializer
    consumer:
      group-id: invoice-service
      auto-offset-reset: earliest
      value-deserializer: org.springframework.kafka.support.serializer.ErrorHandlingDeserializer
      properties:
        spring.deserializer.value.delegate.class: org.springframework.kafka.support.serializer.JsonDeserializer
        spring.json.trusted.packages: com.shop.events

// Producer
kafka.send("orders", order.id().toString(), new OrderPlaced(order.id(), order.total()))
     .whenComplete((result, ex) -> { if (ex != null) log.error("Publish failed", ex); });

// Consumer
@KafkaListener(topics = "orders")
void onOrderPlaced(OrderPlaced event) {
    invoices.create(event.orderId(), event.total());
}

@Configuration
class RabbitConfig {
    @Bean TopicExchange orders() { return new TopicExchange("orders"); }
    @Bean Queue emailQueue() { return QueueBuilder.durable("email.orders").build(); }
    @Bean Binding emailBinding() {
        return BindingBuilder.bind(emailQueue()).to(orders()).with("order.*");   // order.placed, order.cancelled
    }
}

// Producer
rabbit.convertAndSend("orders", "order.placed", new OrderPlaced(order.id()));

// Consumer: acknowledged when the method returns normally
@RabbitListener(queues = "email.orders")
void onOrder(OrderPlaced event) { emails.confirmation(event.orderId()); }

# WRONG (default): a failing message loops forever

# RIGHT: rejected messages go to a dead-letter exchange
spring:
  rabbitmq:
    listener:
      simple:
        default-requeue-rejected: false

@Bean Queue emailQueue() {
    return QueueBuilder.durable("email.orders")
        .deadLetterExchange("orders.dlx")
        .build();
}

public record OrderPlaced(
    UUID eventId,            // unique: lets consumers drop duplicates
    Instant occurredAt,
    Long orderId,            // the aggregate — also the message key
    Long customerId,
    BigDecimal total,
    int schemaVersion        // evolves with the contract
) {}

// WRONG: two identical messages — duplicate or two real orders?
{"orderId": 42, "total": 99.90}

// RIGHT
{"eventId": "7f3c2a10-...", "occurredAt": "2024-05-10T14:32:01Z", "orderId": 42, "total": 99.90}
